export const duration=40;
export const config={title:'RDL 重佈線層',sceneLabel:'兩條封裝配線跨越晶粒邊界，種子層去除後才彼此隔離',question:'接點，延伸到晶粒以外',overview:34,notes:['採單層銅半加成法：介電開窗、黏著／銅種子層、圖案化光阻、電鍍、去光阻、去外露種子及黏著層、保護介電層開接點。從準備好的重組面開始，省略各步搬運及清洗。','俯視顯示兩條線，A線剖面同步放大原焊墊的開窗接觸。種子層未蝕除前，兩線經連續薄金屬相連，不能稱為隔離。線下種子與黏著層保留；外露區按銅、黏著層先後移除，圖中合併表示。','電鍍電源負端接種子、正端接陽極。槽液與陽極以功能符號表示；不繪製漂浮粒子代替配線。薄層厚度放大、時間壓縮，不模擬電流分布、蝕刻側蝕或導通數值，不包含CMP、多層RDL或凸塊。'],sources:[['Fraunhofer IZM：重佈線、介電與電鍍種子','https://www.izm.fraunhofer.de/en/abteilungen/wafer-level-system-integration/leistungsangebot/hd_redistribution.html'],['Fraunhofer IZM：去光阻與種子層化學','https://blog.izm.fraunhofer.de/alternative-chemicals-for-processing/'],['IMAPS：細線RDL的種子層蝕刻','https://imapsource.org/article/57449-enabling-a-robust-copper-seed-etch-process-for-fine-line-rdl-by-electroplating-on-a-thin-pvd-seed-layer'],['Atotech：光阻開口內的銅電鍍','https://www.atotech.com/wp-content/uploads/2019/03/2018-09-14_IMAPS2018_Upscaling-panel-size-for-Cu-plating-on-FOPLP-applications-to-reduce-manufacturing_rev.pdf']]};
export const steps=[{end:6,title:'介電層開窗',key:5,what:'介電層覆蓋重組面，只在原始焊墊上開窗。',detail:'未開窗處維持絕緣；右方模封區不是矽。'}, {end:10,title:'連續種子層',key:9,what:'薄黏著／銅種子層覆蓋表面並接觸開窗內的焊墊。',detail:'種子層先連成一片，為電鍍供電。'}, {end:15,title:'光阻定義配線',key:14,what:'圖案化光阻留下兩條配線開口，從晶粒焊墊延伸到外側。',detail:'紫色光阻遮住其餘區域。'}, {end:22,title:'通電鍍銅增厚',key:20,what:'電源透過連續種子層供電，銅在光阻開口內逐漸增厚。',detail:'A線剖面可見金屬經開窗接到原焊墊，沒有隔著介電層導通。'}, {end:26,title:'去除光阻',key:25,what:'去光阻後露出兩條厚銅線與線間的薄種子層。',detail:'此時仍有連續種子，兩條線還未隔離。'}, {end:31,title:'蝕除外露種子',key:30.5,what:'移除線外的種子與黏著層，線下保留，兩條配線才彼此隔離。',detail:'薄層消失代表蝕刻移除；不能連同厚銅線一起刪去。'}, {end:36,title:'保護層與新接點',key:34.5,what:'保護介電層覆蓋線路，保留外移接點開口。',detail:'A、B是彼此分離的兩條配線；未加入凸塊。'}, {end:40,title:'完成表面移交',key:36.5,what:'完成表面離開，新待加工表面進場。',detail:'成品上的銅線不會倒回消失。'}];
export const ramp=(t,a,b)=>Math.max(0,Math.min(1,(t-a)/(b-a)));export const ease=x=>x*x*(3-2*x);
export function stateAt(t){t=Math.max(0,Math.min(duration-.0001,t));const index=steps.findIndex(s=>t<s.end);return {t,index,step:steps[index],dielectric:ramp(t,1,3),via:ramp(t,3,5),seed:ramp(t,6,9),resist:ramp(t,10,13),plate:ramp(t,15.5,21.5),strip:ramp(t,22,25.5),etch:ramp(t,26,30),cap:ramp(t,31,34),entry:ease(ramp(t,0,1)),exit:ease(ramp(t,37,39.5)),power:t>=15&&t<22,isolated:t>=30};}
